    const enriched = await Promise.all(items.map(async (event) => {
      try {
        const registrationPayload = await registrationApi.byEvent(idOf(event))
        const registrationData = registrationPayload?.data?.data || registrationPayload?.data || registrationPayload
        return { ...event, registrationCount: registrationData?.registrationCount ?? registrationData?.registrations?.length ?? 0 }
      } catch {
        return { ...event, registrationCount: 0 }
      }
    }))
