function AdminContacts() {
  const [contacts, setContacts] = useState([])
  const [modal, setModal] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  async function load() { setLoading(true); try { const payload = await contactApi.list(); setContacts(getList(payload, ['contacts', 'data'])); setError('') } catch (requestError) { setError(requestError.message || 'Unable to load contacts.') } finally { setLoading(false) } }
  useEffect(() => { load() }, [])
  async function toggle(contact) { try { const payload = await contactApi.update(idOf(contact), { isActive: !contact.isActive }); const updated = unwrap(payload)?.contact || unwrap(payload) || { ...contact, isActive: !contact.isActive }; setContacts((items) => items.map((item) => idOf(item) === idOf(contact) ? { ...item, ...updated, isActive: updated.isActive ?? !contact.isActive } : item)) } catch (requestError) { setError(requestError.message || 'Unable to update contact.') } }
  async function remove(contact) { if (!window.confirm(`Delete ${contact.label}?`)) return; try { await contactApi.remove(idOf(contact)); setContacts((items) => items.filter((item) => idOf(item) !== idOf(contact))) } catch (requestError) { setError(requestError.message || 'Unable to delete contact.') } }
  return <><SectionHeading eyebrow="Community access" title="Keep in touch." description="Manage the contact details visible to your event community." action={<button className="cta-button" onClick={() => setModal({})}><Plus size={16} /> Add contact</button>} />{error && <div className="alert error">{error}</div>}<section className="surface table-surface">{loading ? <LoadingRows /> : contacts.length ? <div className="contact-admin-list">{contacts.map((contact) => { const Icon = contactIcon[contact.type] || ContactRound; return <div className="contact-admin-row" key={idOf(contact)}><div className="contact-admin-main"><span className="contact-admin-icon"><Icon size={17} /></span><div><strong>{contact.label}</strong><small>{contact.value}</small></div></div><span className="contact-type">{contact.type || 'other'}</span><span className={`status-chip ${contact.isActive === false ? 'blocked' : ''}`}>{contact.isActive === false ? 'Hidden' : 'Visible'}</span><div className="row-actions"><button title={contact.isActive === false ? 'Show contact' : 'Hide contact'} onClick={() => toggle(contact)}>{contact.isActive === false ? <Eye size={15} /> : <EyeOff size={15} />}</button><button title="Edit" onClick={() => setModal(contact)}><Edit3 size={15} /></button><button title="Delete" onClick={() => remove(contact)}><Trash2 size={15} /></button></div></div> })}</div> : <Empty title="No contacts yet" text="Add a phone number, email, website, or support detail." />}</section>{modal && <ContactModal contact={modal._id ? modal : null} onClose={() => setModal(null)} onSaved={() => { setModal(null); load() }} />}</>
}

function ContactModal({ contact, onClose, onSaved }) {
  const [label, setLabel] = useState(contact?.label || '')
  const [value, setValue] = useState(contact?.value || '')
  const [type, setType] = useState(contact?.type || 'other')
  const [link, setLink] = useState(contact?.link || '')
  const [isActive, setIsActive] = useState(contact?.isActive !== false)
  const [pending, setPending] = useState(false)
  const [error, setError] = useState('')
  async function submit(event) { event.preventDefault(); setPending(true); setError(''); try { const data = { label: label.trim(), value: value.trim(), type, link: link.trim() || undefined, isActive }; if (contact) await contactApi.update(idOf(contact), data); else await contactApi.create(data); onSaved() } catch (requestError) { setError(requestError.message || 'Unable to save contact.') } finally { setPending(false) } }
  return <div className="modal-backdrop"><div className="modal contact-modal"><div className="modal-head"><div><span className="kicker">Contact directory</span><h2>{contact ? 'Refine this detail.' : 'Add a way to reach you.'}</h2></div><button className="close-button" onClick={onClose} aria-label="Close contact form"><X size={18} /></button></div>{error && <div className="alert error">{error}</div>}<form className="modal-form" onSubmit={submit}><Field name="contact-label" label="Label" value={label} onChange={(event) => setLabel(event.target.value)} placeholder="e.g. Support email" required /><Field name="contact-value" label="Value" value={value} onChange={(event) => setValue(event.target.value)} placeholder="support@example.com" required /><label>Type<select value={type} onChange={(event) => setType(event.target.value)}><option value="phone">Phone</option><option value="email">Email</option><option value="address">Address</option><option value="website">Website</option><option value="social">Social</option><option value="other">Other</option></select></label><Field name="contact-link" label="Link (optional)" value={link} onChange={(event) => setLink(event.target.value)} placeholder="mailto:, tel:, or https://..." /><label className="contact-active-toggle"><input type="checkbox" checked={isActive} onChange={(event) => setIsActive(event.target.checked)} /><span><strong>Show to users</strong><small>Hidden contacts stay available for admin management.</small></span></label><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button className="cta-button" disabled={pending}>{pending ? 'Saving...' : contact ? 'Save contact' : 'Add contact'}</button></div></form></div></div>
}

function AdModal({ ad, onClose, onSaved }) {
  const [title, setTitle] = useState(ad?.title || '')
  const [link, setLink] = useState(ad?.link || '')
  const [image, setImage] = useState(null)
  const [preview, setPreview] = useState(ad?.image || '')
  const [pending, setPending] = useState(false)
  const [error, setError] = useState('')
  function chooseImage(file) { if (!file) return; if (!file.type.startsWith('image/')) { setError('Please choose an image file.'); return } setImage(file); const reader = new FileReader(); reader.onload = () => setPreview(reader.result); reader.readAsDataURL(file) }
  async function submit(event) { event.preventDefault(); setPending(true); setError(''); try { new URL(link); if (ad) await adApi.update(idOf(ad), title.trim() || undefined, link.trim(), image); else await adApi.create(title.trim(), link.trim(), image); onSaved() } catch (requestError) { setError(requestError.message || 'Please enter a valid URL.') } finally { setPending(false) } }
  return <div className="modal-backdrop"><div className="modal ad-modal"><div className="modal-head"><div><span className="kicker">{ad ? 'Edit ad' : 'New ad'}</span><h2>{ad ? 'Refine the placement.' : 'Put your campaign in view.'}</h2></div><button className="close-button" onClick={onClose}><X size={18} /></button></div>{error && <div className="alert error">{error}</div>}<form onSubmit={submit} className="modal-form"><Field name="adTitle" label="Title" value={title} onChange={(event) => setTitle(event.target.value)} placeholder="e.g. Summer campaign" required /><Field name="adLink" label="Destination URL" type="url" value={link} onChange={(event) => setLink(event.target.value)} placeholder="https://example.com" required /><label className="image-upload-field"><span>Ad image</span>{preview && <img className="image-preview ad-preview" src={preview} alt="Ad preview" />}<span className="image-upload-control"><ImagePlus size={20} /><span><strong>{image?.name || (preview ? 'Change ad image' : 'Choose an ad image')}</strong><small>JPG, PNG or WEBP</small></span><b>Browse</b><input type="file" accept="image/*" onChange={(event) => chooseImage(event.target.files[0])} required={!ad} /></span></label><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button className="cta-button" disabled={pending}>{pending ? 'Saving...' : ad ? 'Save changes' : 'Publish ad'}</button></div></form></div></div>
}

