function MyRegistrations() {
  const [items, setItems] = useState([])
  const [message, setMessage] = useState('')
  const [loading, setLoading] = useState(true)
  const [cancelItem, setCancelItem] = useState(null)
  const [pending, setPending] = useState(false)
  useEffect(() => { setLoading(true); registrationApi.mine().then((payload) => setItems(getList(payload, ['registrations']))).catch((error) => setMessage(error.message || 'Unable to load registrations.')).finally(() => setLoading(false)) }, [])
  async function cancel() { const eventId = idOf(cancelItem?.event); if (!eventId) return; setPending(true); try { await registrationApi.remove(eventId); const nextIds = new Set(registrationCache.ids || []); nextIds.delete(String(eventId)); registrationCache.ids = nextIds; setItems(items.filter((entry) => idOf(entry.event) !== eventId)); setCancelItem(null) } catch (error) { setMessage(error.message) } finally { setPending(false) } }
  return <><SectionHeading eyebrow="Your calendar" title="Your registrations." description="The events you chose to make time for." />{message && <div className="alert error">{message}</div>}{loading ? <SavedListSkeleton /> : <div className="saved-list">{items.length ? items.map((item) => { const event = item.event || item; const eventDate = event?.date || fallbackDate; return <div className="saved-event registration-card detail-clickable" role="button" tabIndex={0} key={idOf(item)} onClick={() => go(`/events/${idOf(event)}`)} onKeyDown={(eventItem) => { if (eventItem.key === 'Enter' || eventItem.key === ' ') { eventItem.preventDefault(); go(`/events/${idOf(event)}`) } }}><div className="saved-event-image" style={{ backgroundImage: `url(${event.image || eventImage})` }}><div className="saved-date"><b>{new Date(eventDate).toLocaleString('en', { day: '2-digit' })}</b><span>{new Date(eventDate).toLocaleString('en', { month: 'short' })}</span></div></div><div className="saved-event-info"><span className="saved-event-eyebrow"><Ticket size={13} /> Registered</span><strong>{event?.title || 'Event'}</strong><span className="saved-event-subtitle">{event?.subtitle || 'A thoughtful event for people who like to learn, connect, and leave with something new.'}</span><span className="saved-event-meta">{event?.location || 'Location pending'} · {timeLabel(event?.date)}</span></div><button type="button" className="text-button registration-cancel" onClick={(clickEvent) => { clickEvent.stopPropagation(); setCancelItem(item) }}>Cancel registration</button></div> }) : <Empty title="No registrations yet" text="Browse events and reserve your first place." />}</div>}{cancelItem && <ConfirmCancelRegistration item={cancelItem} pending={pending} onCancel={() => setCancelItem(null)} onConfirm={cancel} />}</>
}
function SavedEvents() {
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [message, setMessage] = useState('')
  const [removeItem, setRemoveItem] = useState(null)
  const [pending, setPending] = useState(false)
  useEffect(() => { setLoading(true); savedEventApi.list().then((payload) => setItems(getList(payload, ['savedEvents', 'events']))).catch((error) => setMessage(error.message || 'Unable to load saved events.')).finally(() => setLoading(false)) }, [])
  async function remove() { const eventId = idOf(removeItem?.event || removeItem); if (!eventId) return; setPending(true); try { await savedEventApi.remove(eventId); const nextIds = new Set(savedEventCache.ids || []); nextIds.delete(String(eventId)); savedEventCache.ids = nextIds; setItems(items.filter((item) => idOf(item.event || item) !== eventId)); setRemoveItem(null) } catch (error) { setMessage(error.message || 'Unable to remove saved event.') } finally { setPending(false) } }
  return <><SectionHeading eyebrow="Your shortlist" title="Saved for later." description="Keep the events that caught your eye close by." />{message && <div className="alert error">{message}</div>}{loading ? <SavedListSkeleton /> : <div className="saved-list">{items.length ? items.map((item) => { const event = item.event || item; return <div className="saved-event detail-clickable" role="button" tabIndex={0} key={idOf(event)} onClick={() => go(`/events/${idOf(event)}`)} onKeyDown={(eventItem) => { if (eventItem.key === 'Enter' || eventItem.key === ' ') { eventItem.preventDefault(); go(`/events/${idOf(event)}`) } }}><div className="saved-event-image" style={{ backgroundImage: `url(${event.image || eventImage})` }}><div className="saved-date saved-bookmark"><Bookmark size={17} /></div></div><div className="saved-event-info"><span className="saved-event-eyebrow"><Bookmark size={13} /> Saved event</span><strong>{event.title || 'Event'}</strong><span>{event.location || 'Location pending'} · {dateLabel(event.date)}</span></div><button className="text-button" onClick={(clickEvent) => { clickEvent.stopPropagation(); setRemoveItem(item) }}>Remove</button></div> }) : <Empty title="No saved events" text="Use the bookmark on an event to keep it here." />}</div>}{removeItem && <ConfirmRemoveSavedEvent item={removeItem} pending={pending} onCancel={() => setRemoveItem(null)} onConfirm={remove} />}</>
}
function SavedListSkeleton() { return <div className="saved-list saved-list-skeleton"><span /><span /><span /></div> }
function ReadOnlyProfile({ session }) { const [pending, setPending] = useState(false); const [message, setMessage] = useState(null); async function submit(event) { event.preventDefault(); setPending(true); setMessage(null); const form = new FormData(event.currentTarget); try { await userApi.updateMyProfile({ name: form.get('name').trim(), dateOfBirth: form.get('dateOfBirth') || undefined, phone: form.get('phone').trim(), gender: form.get('gender'), otherDetails: form.get('otherDetails').trim() }); setMessage({ text: 'Profile updated successfully.', success: true }) } catch (error) { setMessage({ text: error.message, error: true }) } finally { setPending(false) } } return <><SectionHeading eyebrow="Your details" title="A little about you." description="Keep your attendee profile ready for every room." /><section className="surface profile-surface"><div className="profile-orb"><UserRound size={32} /></div><h2>{nameOf(session)}</h2><p>{session.email || 'Email unavailable'}</p>{message && <div className={`alert ${message.error ? 'error' : 'success'}`}>{message.text}</div>}<form className="profile-form" onSubmit={submit}><div className="form-grid"><Field name="name" label="Full name" defaultValue={typeof session.name === 'string' ? session.name : `${session.name?.firstName || ''} ${session.name?.lastName || ''}`.trim()} required /><Field name="dateOfBirth" label="Date of birth" type="date" defaultValue={session.dateOfBirth ? new Date(session.dateOfBirth).toISOString().slice(0, 10) : ''} /></div><div className="form-grid"><Field name="phone" label="Phone" defaultValue={session.phone || ''} /><Field name="gender" label="Gender" type="select" options={['male', 'female', 'other']} defaultValue={session.gender || ''} /></div><label>Other details<textarea name="otherDetails" rows="3" defaultValue={session.otherDetails || ''} placeholder="Tell us a little more about yourself" /></label><button className="cta-button" disabled={pending}>{pending ? 'Saving...' : 'Save profile'}</button></form></section></> }
function Profile({ session }) {
  const [pending, setPending] = useState(false)
  const [message, setMessage] = useState(null)
  const [image, setImage] = useState(null)
  const [preview, setPreview] = useState(session.profileImage || '')
  function chooseImage(file) { if (!file) return; if (!file.type.startsWith('image/')) { setMessage({ text: 'Please choose an image file.', error: true }); return } if (file.size > 5 * 1024 * 1024) { setMessage({ text: 'Please choose an image smaller than 5 MB.', error: true }); return } setImage(file); const reader = new FileReader(); reader.onload = () => setPreview(reader.result); reader.readAsDataURL(file) }
  async function submit(event) { event.preventDefault(); setPending(true); setMessage(null); const form = new FormData(event.currentTarget); try { await userApi.updateMyProfile({ name: form.get('name').trim(), dateOfBirth: form.get('dateOfBirth') || undefined, phone: form.get('phone').trim(), gender: form.get('gender'), otherDetails: form.get('otherDetails').trim() }, image); setMessage({ text: 'Profile updated successfully.', success: true }) } catch (error) { setMessage({ text: error.message, error: true }) } finally { setPending(false) } }
  const name = typeof session.name === 'string' ? session.name : `${session.name?.firstName || ''} ${session.name?.lastName || ''}`.trim()
  return <><SectionHeading eyebrow="Your details" title="A little about you." description="Keep your attendee profile ready for every room." /><section className="surface profile-surface"><div className="profile-orb profile-image" style={preview ? { backgroundImage: `url(${preview})` } : {}}>{!preview && <UserRound size={32} />}</div><label className="profile-upload">Change profile image<input type="file" accept="image/*" capture="user" onChange={(event) => chooseImage(event.target.files[0])} /></label><h2>{nameOf(session)}</h2><p>{session.email || 'Email unavailable'}</p>{message && <div className={`alert ${message.error ? 'error' : 'success'}`}>{message.text}</div>}<form className="profile-form" onSubmit={submit}><div className="form-grid"><Field name="name" label="Full name" defaultValue={name} required /><Field name="dateOfBirth" label="Date of birth" type="date" defaultValue={session.dateOfBirth ? new Date(session.dateOfBirth).toISOString().slice(0, 10) : ''} /></div><div className="form-grid"><Field name="phone" label="Phone" defaultValue={session.phone || ''} /><Field name="gender" label="Gender" type="select" options={['male', 'female', 'other']} defaultValue={session.gender || ''} /></div><label>Other details<textarea name="otherDetails" rows="3" defaultValue={session.otherDetails || ''} placeholder="Tell us a little more about yourself" /></label><button className="cta-button" disabled={pending}>{pending ? 'Saving...' : 'Save profile'}</button></form><div className="profile-grid"><span><small>Phone</small><b>{session.phone || 'Not added'}</b></span><span><small>Gender</small><b>{session.gender || 'Not added'}</b></span><span><small>Date of birth</small><b>{dateLabel(session.dateOfBirth)}</b></span><span><small>Member since</small><b>{dateLabel(session.createdAt)}</b></span></div></section></>
}
function SectionHeading({ eyebrow, title, description, action }) { return <section className="section-heading"><div><span className="kicker">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action}</section> }
function Empty({ title, text }) { return <div className="empty"><div className="empty-icon"><CalendarDays size={18} /></div><strong>{title}</strong><span>{text}</span></div> }
function LoadingRows() { return <div className="loading-rows"><span /><span /><span /></div> }

export default App
